//! Version-four protocol boundary for reflection code generated by the derive crate.
//!
//! This module is intentionally separate from the existing generated-code
//! protocol. The submodules define ownership boundaries for the runtime
//! contracts that generated code will consume. Their public factories are added
//! only when the runtime exposes matching, type-safe construction seams; raw
//! registration fragments and caller-chosen identities are not part of this
//! protocol.

/// Safe field and variant adapter contracts used by generated implementations.
pub mod access;
/// Typed capability registration contracts used by generated implementations.
pub mod capability;
/// Safe construction adapter contracts used by generated implementations.
pub mod construct;
/// Type registration and descriptor contracts used by generated implementations.
pub mod descriptor;
/// Structural generic and type-expression contracts used by generated code.
pub mod expression;
/// Typed implementation declaration and application metadata used by generated code.
pub mod impls;
/// Typed invocation adapter contracts used by generated implementations.
pub mod invoke;
/// Internal derive support used to apply conditional attributes before v4 emission.
#[cfg(feature = "derive")]
pub mod macro_support;
/// Compile-time handshake for derive/runtime compatibility.
pub mod protocol;
/// Typed trait declaration and application metadata used by generated code.
pub mod traits;

pub use protocol::PROTOCOL_VERSION;
/// Linked registration contracts consumed while building reflection contexts.
pub mod registration;
/// Shared dynamic-value mode and typed value conversion contracts.
pub mod value;
